import sys

def can_reconstruct_words(lengths):
    if len(set(lengths)) != len(lengths):
        return False
    words = []
    used_prefixes = set()
    for length in sorted(lengths):
        candidate = None
        for i in range(2 ** length):
            word = bin(i)[2:].zfill(length)
            if all(not word.startswith(prefix) for prefix in used_prefixes):
                candidate = word
                break
        if candidate is None:
            return False
        words.append(candidate)
        used_prefixes.update(word[:i] for i in range(1, length + 1))
    return words

input = sys.stdin.read().strip().split()
N = int(input[0])
lengths = list(map(int, input[1:]))

words = can_reconstruct_words(lengths)
if words is False:
    print("NO")
else:
    print("YES")
    for word in words:
        print(word)
